#include <iostream>
#include <string>

int main() {
    std::string zona = "Norte";

    std::cout << zona;

    return 0;
}

#include <iostream>
#include <string>

int main() {
    ___ etiqueta = "Puerta A";
    std::cout << etiqueta;

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string etiqueta;

    std::cout << "[" << etiqueta << "]";

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string zona = "Norte";

    std::string registro = zona;

    zona = "Sur";

    std::cout << registro << " / " << zona;

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string estado = "Abierto";

    estado = ___;

    std::cout << estado;

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string sala = "Sala";
    std::string numero = "2";

    std::string nombre = sala + " " + numero;

    std::cout << nombre;

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string a = "Puerta";
    std::string b = "B";

    std::cout << a + b << "\n" << a + " " + b;

    return 0;
}

